list_tax_zones.code:
const response = await client.taxZones.listTaxZones({limit: 2});
for (const taxZone of response.map.tax_zones) {
    console.log(taxZone.id, taxZone.name);
}
console.log(response.map.pagination.total, response.map.pagination.next_page);

create_tax_zone.code:
const response = await client.taxZones.createTaxZone({
    tax_zone: {
        name: 'Sydney Metro',
        countries: [{id: 12}],
        states: [{id: 67}],
        post_code: ['2000', '3000'],
    },
});
console.log(response.map.tax_zone.id, response.map.tax_zone.post_code);

get_tax_zone.code:
const response = await client.taxZones.getTaxZone(1);
const taxZone = response.map.tax_zone;
console.log(taxZone.name, taxZone.countries, taxZone.states, taxZone.post_code);

